-- ============================================
-- LUMA — Enrichissement Thématique 4 (Voyage) : scénarios longs
-- ============================================

update scenarios set content = '{"characters": {"agent": "l''agent de la compagnie"}, "start_node": "n1", "nodes": {"n1": {"speaker": "agent", "text": "I see you missed your connection. Let''s find a solution.", "text_fr": "Je vois que vous avez raté votre correspondance. Trouvons une solution.", "choices": [{"text": "What''s the next available flight?", "next": "n2"}, {"text": "This is really frustrating — is this covered by the airline?", "next": "n2b"}]}, "n2": {"speaker": "agent", "text": "There''s one in 3 hours, but it''s fully booked. There''s also one tomorrow with a guaranteed seat.", "text_fr": "Il y en a un dans 3 heures, mais complet. Il y en a aussi un demain avec une place garantie.", "choices": [{"text": "Can you put me on standby for the one in 3 hours?", "next": "n3"}, {"text": "I''ll take the guaranteed seat tomorrow.", "next": "n3b"}]}, "n2b": {"speaker": "agent", "text": "Since it was our delay that caused the miss, yes, we''ll cover accommodation and rebooking.", "text_fr": "Comme c''est notre retard qui a causé ça, oui, on couvre l''hébergement et le nouveau billet.", "choices": [{"text": "That''s a relief, thank you. What are my options?", "next": "n2"}]}, "n3": {"speaker": "agent", "text": "You''re #2 on the standby list — decent chance!", "text_fr": "Vous êtes 2e sur liste d''attente — bonne chance !", "choices": [{"text": "Fingers crossed, thank you. What if I don''t make it?", "next": "n4"}]}, "n3b": {"speaker": "agent", "text": "Good call, I''ll also arrange a hotel for tonight.", "text_fr": "Bon choix, je vous arrange aussi un hôtel pour ce soir.", "choices": [{"text": "That''s very helpful, thank you.", "next": "end_hotel"}]}, "n4": {"speaker": "agent", "text": "If standby doesn''t work out, we''ll automatically move you to tomorrow''s guaranteed seat with a hotel.", "text_fr": "Si la liste d''attente ne marche pas, on vous bascule automatiquement sur le vol garanti de demain avec un hôtel.", "choices": [{"text": "That''s reassuring, thank you for planning ahead.", "next": "n5"}]}, "n5": {"speaker": "agent", "text": "Good news — a seat opened up, you''re confirmed for tonight!", "text_fr": "Bonne nouvelle — une place s''est libérée, vous êtes confirmé pour ce soir !", "choices": [{"text": "That''s fantastic, thank you so much!", "next": "end_standby"}]}, "end_hotel": {"speaker": "agent", "text": "You''re all set for tomorrow''s flight, room 214 at the airport hotel.", "text_fr": "Tout est réglé pour le vol de demain, chambre 214 à l''hôtel de l''aéroport.", "end": true, "ending_label": "Solution de secours trouvée 🏨"}, "end_standby": {"speaker": "agent", "text": "Great, enjoy your flight, and sorry again for the trouble!", "text_fr": "Parfait, bon vol, et encore désolé pour le désagrément !", "end": true, "ending_label": "Standby réussi malgré la tension 🎉"}}}'::jsonb, is_playable = true
where title = 'Une correspondance ratée avec plusieurs obstacles'
  and theme_id = (select id from scenario_themes where position = 4 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"staff": "le personnel de l''aéroport"}, "start_node": "n1", "nodes": {"n1": {"speaker": "staff", "text": "First, your gate has changed to C22.", "text_fr": "D''abord, votre porte a changé pour la C22.", "choices": [{"text": "Thanks for the heads up, how far is that?", "next": "n2"}, {"text": "That''s the third change today, is everything okay?", "next": "n2b"}]}, "n2": {"speaker": "staff", "text": "About a 10-minute walk. Also, security lines are quite long today.", "text_fr": "Environ 10 minutes à pied. Aussi, les files de sécurité sont longues aujourd''hui.", "choices": [{"text": "I should hurry then, thank you.", "next": "n3"}]}, "n2b": {"speaker": "staff", "text": "Just a busy day at the airport, nothing to worry about specifically.", "text_fr": "Juste une journée chargée à l''aéroport, rien de particulier à craindre.", "choices": [{"text": "Okay, good to know. I''ll head that way then.", "next": "n3"}]}, "n3": {"speaker": "staff", "text": "One more thing — your flight is delayed by 45 minutes.", "text_fr": "Une dernière chose — votre vol a 45 minutes de retard.", "choices": [{"text": "Well, at least I won''t miss it now!", "next": "n4"}, {"text": "This trip has been one thing after another.", "next": "n4b"}]}, "n4": {"speaker": "staff", "text": "That''s the spirit! Actually, there''s a silver lining — you''ve been upgraded due to overbooking.", "text_fr": "Voilà le bon esprit ! En fait, il y a une bonne nouvelle — vous avez été surclassé suite à un surbooking.", "choices": [{"text": "Are you serious? That''s amazing news!", "next": "end_upgrade"}]}, "n4b": {"speaker": "staff", "text": "I completely understand, travel days can be exhausting. Let me see what I can do to make it up to you.", "text_fr": "Je comprends totalement, les jours de voyage peuvent être épuisants. Laissez-moi voir ce que je peux faire pour compenser.", "choices": [{"text": "I''d appreciate that, thank you.", "next": "n5"}]}, "n5": {"speaker": "staff", "text": "I''ve added a meal voucher and priority boarding to your ticket.", "text_fr": "J''ai ajouté un bon repas et l''embarquement prioritaire à votre billet.", "choices": [{"text": "That''s really kind, thank you for turning this around.", "next": "end_compensated"}]}, "end_upgrade": {"speaker": "staff", "text": "Enjoy business class! Sometimes delays work out in your favor.", "text_fr": "Profitez de la classe affaires ! Parfois les retards jouent en votre faveur.", "end": true, "ending_label": "Journée compliquée, fin en beauté ✨"}, "end_compensated": {"speaker": "staff", "text": "Safe travels, and thank you for your patience today.", "text_fr": "Bon voyage, et merci pour votre patience aujourd''hui.", "end": true, "ending_label": "Imprévus surmontés et compensés 😊"}}}'::jsonb, is_playable = true
where title = 'Un voyage avec imprévus en cascade'
  and theme_id = (select id from scenario_themes where position = 4 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"passenger": "une passagère âgée"}, "start_node": "n1", "nodes": {"n1": {"speaker": "passenger", "text": "Excuse me, I can''t find my gate and my phone died. Could you help?", "text_fr": "Excusez-moi, je ne trouve pas ma porte et mon téléphone est mort. Pouvez-vous m''aider ?", "choices": [{"text": "Of course, let me look at your ticket.", "next": "n2"}, {"text": "Absolutely, and would you like to borrow my charger too?", "next": "n2b"}]}, "n2": {"speaker": "passenger", "text": "Thank you, here it is — gate D8.", "text_fr": "Merci, la voici — porte D8.", "choices": [{"text": "That''s actually on my way, I''ll walk you there.", "next": "n3"}, {"text": "It''s just down this hall, follow the signs.", "next": "n3b"}]}, "n2b": {"speaker": "passenger", "text": "Oh, that would be wonderful, thank you so much!", "text_fr": "Oh, ce serait merveilleux, merci beaucoup !", "choices": [{"text": "No problem at all, here it is.", "next": "n2"}]}, "n3": {"speaker": "passenger", "text": "You''re so kind, thank you for walking with me!", "text_fr": "Vous êtes si gentil(le), merci de m''accompagner !", "choices": [{"text": "It''s really no trouble at all.", "next": "n4"}]}, "n3b": {"speaker": "passenger", "text": "Thank you so much for your help!", "text_fr": "Merci beaucoup pour votre aide !", "choices": [{"text": "Anytime, I hope you have a smooth flight.", "next": "n4"}]}, "n4": {"speaker": "passenger", "text": "You know, my grandson is about your age. You remind me of him.", "text_fr": "Vous savez, mon petit-fils a à peu près votre âge. Vous me le rappelez.", "choices": [{"text": "That''s really sweet, tell me about him.", "next": "end_connection"}, {"text": "I''m glad I could help, safe travels!", "next": "end_simple"}]}, "end_connection": {"speaker": "passenger", "text": "(shares a warm story about her family, genuinely grateful for the company)", "text_fr": "(partage une histoire chaleureuse sur sa famille, sincèrement reconnaissante pour la compagnie)", "end": true, "ending_label": "Belle connexion humaine 💛"}, "end_simple": {"speaker": "passenger", "text": "Thank you, dear. Safe travels to you too.", "text_fr": "Merci, cher/chère. Bon voyage à vous aussi.", "end": true, "ending_label": "Geste généreux apprécié 🙏"}}}'::jsonb, is_playable = true
where title = 'Aider un autre passager en difficulté'
  and theme_id = (select id from scenario_themes where position = 4 and language_id = (select id from languages where code = 'en'));
